import { Vec2 } from "kaplay";
import { k } from "../../main";
import { uiState } from "../uiState";
import { UI_COLORS, UI_FONT_SIZES } from "./theme";
import { uiHitRegion } from "./hitRegion";
import {
	playUiClickSound,
	playUiHoverSound,
} from "../../services/audio/uiSoundService";
import type { InputPromptAction } from "../../services/input/inputPromptService";
import { createInputPromptRow } from "./inputPrompt";

export interface UiActionButtonProps {
	pos: Vec2;
	text: string;
	onClick: () => void;
	onDisabledClick?: () => void;
	size?: Vec2;
	selected?: boolean;
	primary?: boolean;
	disabled?: boolean;
	requirementsMet?: boolean;
	notification?: boolean;
	icon?: string;
	iconSize?: number;
	promptAction?: InputPromptAction;
}

export function createUiActionButton(parent: ReturnType<typeof k.add>, {
	pos,
	text,
	onClick,
	onDisabledClick,
	size = k.vec2(120, 32),
	selected = false,
	primary = false,
	disabled = false,
	requirementsMet,
	notification = false,
	icon,
	iconSize = 14,
	promptAction,
}: UiActionButtonProps) {
	const fill = primary
		? UI_COLORS.accent
		: selected ? UI_COLORS.panelHover : UI_COLORS.panel;
	const foreground = primary ? UI_COLORS.background : UI_COLORS.text;
	const requirementColor = requirementsMet === undefined
		? undefined
		: requirementsMet ? UI_COLORS.accent : UI_COLORS.danger;
	const resolvedForeground = requirementColor ?? (
		disabled ? UI_COLORS.muted : foreground
	);
	const button = parent.add([
		k.pos(pos),
		k.rect(size.x, size.y),
		uiHitRegion(size),
		k.color(...fill),
		k.outline(1, k.rgb(...(
			requirementColor ?? (primary || selected ? UI_COLORS.accent : UI_COLORS.border)
		))),
	]);
	button.add([
		k.text(text, { size: UI_FONT_SIZES.tiny, font: "unscii" }),
		k.pos(size.x / 2 + (icon || promptAction ? 6 : 0), size.y / 2),
		k.anchor("center"),
		k.color(...resolvedForeground),
	]);
	if (notification) {
		button.add([
			k.text("!", { size: UI_FONT_SIZES.tiny, font: "unscii" }),
			k.pos(size.x - 9, 5),
			k.anchor("topright"),
			k.color(...UI_COLORS.warning),
		]);
	}
	if (icon) {
		button.add([
			k.sprite(icon, { width: iconSize, height: iconSize }),
			k.pos(14, size.y / 2),
			k.anchor("center"),
			k.color(...resolvedForeground),
		]);
	}
	if (promptAction) {
		createInputPromptRow(button, {
			pos: k.vec2(14, size.y / 2),
			prompts: [{ action: promptAction }],
			align: "center",
			color: resolvedForeground,
			iconHeight: 20,
		})
	}
	if (disabled) {
		if (onDisabledClick) button.onClick(onDisabledClick);
	} else {
		button.onClick(() => {
			playUiClickSound();
			onClick();
		});
		button.onHover(() => {
			uiState.isOverUI = true;
			button.color = k.rgb(...(primary ? UI_COLORS.text : UI_COLORS.panelHover));
			playUiHoverSound();
		});
		button.onHoverEnd(() => {
			uiState.isOverUI = false;
			button.color = k.rgb(...fill);
		});
	}
	return button;
}
