function selectGravityShrineDestinations(
	grid: HexGrid,
	map: GenerationMap,
	origin: { q: number; r: number }
) {
	const seed = currentRunSeed ?? 1;
	const openCells = map
		.getAllCells()
		.filter(
			(cell) =>
				!cell.solid &&
				!cell.tags.has("room_anchor") &&
				!cell.tags.has("resource_node") &&
				!cell.tags.has("hazard")
		)
		.sort(
			(a, b) =>
				cavernHash(seed, a.coord, 4817) - cavernHash(seed, b.coord, 4817)
		)
	const preferred = openCells.filter(
		(cell) =>
			hexDistance(origin, cell.coord) >= 12 &&
			!getRoomRole(cell) &&
			hexNeighbors(cell.coord).filter((neighborCoord) => {
				const neighbor = map.getCell(neighborCoord)
				return neighbor && !neighbor.solid
			}).length >= 4
	)
	const fallback = openCells.filter(
		(cell) => hexDistance(origin, cell.coord) >= 5
	)
	const selected: GenCell[] = []
	for (const cell of [...preferred, ...fallback]) {
		if (selected.includes(cell)) continue
		if (
			selected.some(
				(selectedCell) => hexDistance(selectedCell.coord, cell.coord) < 8
			)
		) continue
		selected.push(cell)
		if (selected.length >= 2) break
	}
	for (const cell of fallback) {
		if (selected.length >= 2) break
		if (!selected.includes(cell)) selected.push(cell)
	}
	if (selected.length === 0 && openCells[0]) selected.push(openCells[0])
	return selected
		.map((cell) => grid.hexToScreen(cell.coord));
}

export function spawnFloorExit(
	pos: Vec2,
	objectTags: string[] = [tags.runMap],
	options: {
		onActivated?: () => void
		finaleRequired?: boolean
	} = {}
) {
	const finaleRequired = options.finaleRequired !== false
	currentFloorExitPosition = pos.clone();
	let portalReady = !finaleRequired;
	let previousPhase = getRunPhase();
	let rampShakeCooldown = 0;
	const gravity = spawnGravityPull({
		pos,
		falloff: 1,
		visualizePull: true,
		tags: objectTags,
		targetTags: [
			tags.unit,
			tags.friendly,
			tags.enemy,
			tags.debree,
			tags.projectile,
		],
		tagStrengthMultipliers: {
			[tags.projectile]: 3,
		},
	});
	const portal = spawnLevel({
		pos,
		levelName: "level1",
		visual: "wormhole",
		label: finaleRequired ? "ACTIVATE EXIT" : "NEXT LEVEL",
		portalState: finaleRequired ? "dormant" : "active",
		tags: objectTags,
		onEnter: (_portal, selectLevel, cancel) => {
			if (narrativePrologueActive()) {
				portal.setPortalState("dormant", "SIGNAL JAMMED");
				updateQuestObjective(
					"lost-in-the-daze",
					"THE EXIT SIGNAL IS JAMMED — SURVIVE"
				);
				addThreatTime(60);
				cancel();
				return;
			}
			if (finaleRequired && getRunPhase() !== "exitReady") {
				if (activateRunFinale()) {
					options.onActivated?.();
					portal.setPortalInteractionEnabled(false);
					portal.setPortalState("charging", "");
					k.flash(k.WHITE, 0.22);
					explosionEmitter.emitter.position = portal.pos.clone();
					explosionEmitter.emit(44);
					starsEmitter.emitter.position = portal.pos.clone();
					starsEmitter.emit(28);
				}
				cancel();
				return;
			}
			if (
				contractChallengeActive("fragileDelivery") &&
				deliverVolatileCargoPackage()
			) {
				spawnMapChallengeRewards(
					portal.pos.clone(),
					getContractChallengeRewardCount("fragileDelivery")
				);
				portal.setPortalState("active", "PACKAGE DELIVERED // COLLECT REWARDS");
				cancel();
				return;
			}
			const clearedDepth = getCurrentRunFloor()?.depth ?? 1;
			const clearedFloor = getFloorPositionForDepth(clearedDepth);
			const nextFloor = advanceRunSession();
			if (nextFloor) {
				depositCarriedDebree();
				const summary = checkpointRun(getDepositedDebreeThisRun());
				saveGame("slot1");
				audioService.fadeOutMusic(0.6);
				setTimescale(0.1, 0.35, false);
				showRunClearScreen(summary, () => {
					setTimescale(1, 0.25, false);
					selectLevel(nextFloor.levelKey);
				}, {
					title: `FLOOR ${clearedFloor.floor}.${clearedFloor.subfloor} CLEARED`,
					subtitle: "SALVAGE SECURED  //  ROUTE CONTINUES",
					continueText: "CONTINUE RUN",
				});
				return;
			}
			const cargoReward = extractVolatileCargo();
			if (cargoReward > 0) {
				console.log(
					`Volatile cargo delivered for ${cargoReward} salvage`
				);
			}
			const summary = completeRun("EXTRACTED", extractDebreeRun());
			clearPendingRunEndSummary();
			saveGame("slot1");
			audioService.fadeOutMusic(0.6);
			setTimescale(0.1, 0.35, false);
			showRunClearScreen(summary, () => {
				setTimescale(1, 0.25, false);
				selectLevel("hub");
			}, isDemoBuild() ? {
				title: "DEMO COMPLETE",
				subtitle: "THE FIRST FLOOR IS SECURED  //  THANK YOU FOR PLAYING",
				continueText: "RETURN TO THE WAKE",
			} : undefined);
		},
	});
	if (!finaleRequired) {
		portal.setPortalProgress(1)
		portal.setPortalInteractionEnabled(true)
	}

	registerBatchedEntityUpdate("world", portal, () => {
		if (!finaleRequired) return
		const phase = getRunPhase();
		if (phase === "transition") {
			const progress = getRunFinaleRampProgress();
			const easedProgress = progress * progress * (3 - 2 * progress);
			portal.setPortalProgress(progress);
			gravity.radius = k.lerp(36, 280, easedProgress);
			gravity.strength = k.lerp(8, 125, easedProgress);
			rampShakeCooldown -= k.dt();
			if (progress > 0 && rampShakeCooldown <= 0) {
				k.shake(k.lerp(0.25, 6, progress * progress));
				rampShakeCooldown = k.lerp(0.16, 0.035, progress);
			}
			portal.setPortalState("charging", "");
		}
		if (phase === "finale") {
			if (previousPhase === "transition") {
				k.shake(9);
				k.flash(k.WHITE, 0.85);
			}
			portal.setPortalProgress(0);
			portal.setPortalState("dormant", "");
			gravity.radius = 36;
			gravity.strength = 8;
		}
		if (phase === "exitReady") {
			portal.setPortalProgress(1);
			portal.setPortalInteractionEnabled(true);
		}
		previousPhase = phase;
		if (portalReady || phase !== "exitReady") return;
		portalReady = true;
		portal.setPortalProgress(1);
		k.flash(k.WHITE, 0.65);
		portal.setPortalState("active", "NEXT LEVEL");
		k.shake(5);
	});
	portal.onDestroy(() => {
		if (gravity.exists()) k.destroy(gravity);
	});
}

function spawnCargoDeliveryIndicator() {
	const indicator = k.add([
		k.pos(playerObj.pos.clone()),
		k.rotate(0),
		k.opacity(0),
		k.z(40),
		k.layer(layers.game),
		{
			draw() {
				const pulse = k.wave(0.92, 1.08, k.time() * 5);
				const color = k.rgb(255, 155, 55);
				k.drawCircle({
					pos: k.vec2(0),
					radius: 11 * pulse,
					color,
					opacity: this.opacity * 0.14,
					anchor: "center",
				});
				k.drawPolygon({
					pts: [
						k.vec2(-8, -5),
						k.vec2(2, -5),
						k.vec2(2, -9),
						k.vec2(13, 0),
						k.vec2(2, 9),
						k.vec2(2, 5),
						k.vec2(-8, 5),
					],
					color,
					opacity: this.opacity,
					outline: {
						width: 1,
						color: k.WHITE,
						opacity: this.opacity * 0.8,
					},
				});
			},
		},
		tags.runMap,
		tags.gameLoop,
	]);

	registerBatchedEntityUpdate("world", indicator, () => {
		const shouldShow =
			session.volatileCargoActive &&
			session.volatileCargoIntact &&
			!session.volatileCargoDelivered &&
			currentFloorExitPosition !== undefined;
		if (!shouldShow || !currentFloorExitPosition) {
			indicator.opacity = 0;
			return;
		}

		const towardExit = currentFloorExitPosition.sub(playerObj.pos);
		if (towardExit.len() <= 24) {
			indicator.opacity = 0;
			return;
		}

		const direction = towardExit.unit();
		const orbitRadius = k.wave(42, 46, k.time() * 3.5);
		indicator.pos = playerObj.pos.add(direction.scale(orbitRadius));
		indicator.angle = direction.angle();
		indicator.opacity = k.wave(0.72, 1, k.time() * 4.5);
	});
}

