export const HUB_RESTORATION_LAMP_COUNT = 8
const HUB_GREEN = [90, 220, 145] as const
const HUB_LAMP_COLOR = [160, 180, 190] as const
const HUB_BROKEN_LAMP_COLOR = [68, 78, 86] as const
const HAULER_SPEED = 145
const HAULER_CARGO_OFFSETS = [[-3, -4], [0, -6], [3, -4], [-1.5, -2], [1.5, -2]] as const
const MAX_DEBRIS_DISPLAY_PIECES = 45
const DEBRIS_DISPLAY_CLUSTER_RADIUS = 66
const DEBRIS_DISPLAY_VALUES: readonly SalvagePickupValue[] = [
	1,
	1,
	3,
	1,
	5,
	1,
	3,
	1,
	10,
	3,
	1,
	5,
] as const

type HaulerPhase = "waiting" | "outbound" | "scavenging" | "returning"

interface HubRestorationOptions {
	initialLampLevel?: number
}

interface HubRestorationLamp {
	object: GameObj
	isLit(): boolean
	setLit(lit: boolean): void
}

export interface HubRestorationHandle {
	controller: GameObj
	getLamp(level: number): GameObj | undefined
	setLampLit(level: number, lit: boolean): void
	finishLevelReveal(): void
}

export function spawnHubRestoration(
	center: Vec2,
	phaseStationPos: Vec2,
	hubHalfBounds: Vec2,
	options: HubRestorationOptions = {}
): HubRestorationHandle {
	let spawnedThroughLevel = 0
	let lampLevelOverride = options.initialLampLevel !== undefined
	spawnRestorationFloorStamp(center)
	const lamps = spawnRestorationLamps(
		center,
		options.initialLampLevel ?? getHubLevel()
	)
	spawnRestorationLampLightning(center, lamps)
	const debrisDisplay = spawnRestorationDebrisDisplay(center)
	const revealThroughLevel = (level: number) => {
		for (let index = 0; index < lamps.length; index++) {
			lamps[index].setLit(index < level)
		}
	}
	const controller = k.add([
		k.pos(center),
		k.layer(layers.gameEffects),
		k.z(-1),
		{
			update() {
				debrisDisplay.update()
				const level = Math.min(HUB_RESTORATION_LAMP_COUNT, getHubLevel())
				if (!lampLevelOverride) revealThroughLevel(level)
				while (spawnedThroughLevel < level) {
					spawnedThroughLevel++
					spawnRestorationTier(
						center,
						phaseStationPos,
						hubHalfBounds,
						spawnedThroughLevel
					)
				}
			},
		},
		tags.hubRestoration,
		tags.gameLoop,
	])
	controller.update()
	return {
		controller,
		getLamp(level: number) {
			return lamps[level - 1]?.object
		},
		setLampLit(level: number, lit: boolean) {
			lamps[level - 1]?.setLit(lit)
		},
		finishLevelReveal() {
			lampLevelOverride = false
			revealThroughLevel(
				Math.min(HUB_RESTORATION_LAMP_COUNT, getHubLevel())
			)
		},
	}
}

function spawnRestorationFloorStamp(center: Vec2) {
	const stamp = HUB_RESTORATION_FLOOR_STAMP
	const coords = createHubRestorationFloorStampCells()
	const coordKeys = new Set(coords.map((coord) => hexKey(coord)))
	const cells = coords.map((coord) => ({
		coord,
		position: hexToPixel(coord, stamp.hexSize),
		frame: getRunRockGroundTileFrame(
			getHubRestorationFloorStampMaterial(coord) *
				RUN_ROCK_GROUND_VARIANTS_PER_MATERIAL +
				Math.abs(coord.q * 73 + coord.r * 151) %
				RUN_ROCK_GROUND_VARIANTS_PER_MATERIAL
		),
		exposedEdges: hexNeighbors(coord).map(
			(neighbor) => !coordKeys.has(hexKey(neighbor))
		),
	}))
	const tileScale = stamp.hexSize / RUN_ROCK_GROUND_TILE_SOURCE_RADIUS * 1.03
	const stampCenter = center.add(stamp.offset[0], stamp.offset[1])
	let picture: ReturnType<typeof k.endPicture> | undefined
	const floor = k.add([
		k.pos(0, 0),
		k.layer(layers.game2),
		k.z(stamp.z),
		{
			draw() {
				if (!picture) {
					k.beginPicture()
					for (const cell of cells) {
						const frameQuad = k.getSprite(
							RUN_ROCK_GROUND_TILE_SPRITE
						)?.data?.frames[cell.frame]?.q
						const uniform = frameQuad
							? {
								u_uvMin: k.vec2(frameQuad.x, frameQuad.y),
								u_uvMax: k.vec2(
									frameQuad.x + frameQuad.w,
									frameQuad.y + frameQuad.h
								),
								u_seed: Math.abs(cell.coord.q * 37 + cell.coord.r * 101),
								u_edge0: cell.exposedEdges[0] ? 1 : 0,
								u_edge1: cell.exposedEdges[1] ? 1 : 0,
								u_edge2: cell.exposedEdges[2] ? 1 : 0,
								u_edge3: cell.exposedEdges[3] ? 1 : 0,
								u_edge4: cell.exposedEdges[4] ? 1 : 0,
								u_edge5: cell.exposedEdges[5] ? 1 : 0,
							}
							: undefined
						k.drawSprite({
							sprite: RUN_ROCK_GROUND_TILE_SPRITE,
							frame: cell.frame,
							pos: stampCenter.add(cell.position.x, cell.position.y),
							anchor: "center",
							scale: k.vec2(tileScale),
							color: k.rgb(stamp.tint[0], stamp.tint[1], stamp.tint[2]),
							opacity: stamp.opacity,
							shader: frameQuad ? "roomGroundJaggedEdge" : undefined,
							uniform,
						})
					}
					picture = k.endPicture()
				}
				k.drawPicture(picture, {})
			},
		},
		tags.hubRestoration,
		tags.gameLoop,
	])
	floor.onDestroy(() => picture?.free())
	spawnGroundShadowRenderer(
		(position) => coordKeys.has(hexKey(
			pixelToHex(position.sub(stampCenter), stamp.hexSize)
		)),
		[tags.hubRestoration, tags.gameLoop]
	)
}

function spawnRestorationDebrisDisplay(center: Vec2) {
	const pieces: Array<{
		object: GameObj<PosComp | RotateComp>
		basePos: Vec2
		baseAngle: number
		phase: number
		floatSpeed: number
	}> = []
	let displayedCount = -1

	const syncCount = () => {
		const deposited = getHubLifetimeDeposited()
		const maximumDeposit = getHubLevelDefinition(
			HUB_RESTORATION_LAMP_COUNT
		).requiredDeposited
		const depositProgress = k.clamp(deposited / maximumDeposit, 0, 1)
		const nextCount = deposited <= 0
			? 0
			: Math.ceil(Math.sqrt(depositProgress) * MAX_DEBRIS_DISPLAY_PIECES)
		if (nextCount === displayedCount) return
		displayedCount = nextCount
		while (pieces.length > nextCount) {
			const piece = pieces.pop()
			if (piece?.object.exists()) k.destroy(piece.object)
		}
		while (pieces.length < nextCount) {
			pieces.push(spawnRestorationDebrisPiece(center, pieces.length))
		}
	}

	const update = () => {
		syncCount()
		const time = k.time()
		for (const piece of pieces) {
			if (!piece.object.exists()) continue
			piece.object.pos = piece.basePos.add(
				Math.sin(time * piece.floatSpeed + piece.phase) * 1.25,
				Math.cos(time * piece.floatSpeed * 0.72 + piece.phase) * 0.9
			)
			piece.object.angle = piece.baseAngle +
				Math.sin(time * piece.floatSpeed * 0.45 + piece.phase) * 8
		}
	}

	update()
	return { update }
}

function spawnRestorationDebrisPiece(center: Vec2, index: number) {
	const normalizedRadius = Math.sqrt(
		(index + 0.5) / MAX_DEBRIS_DISPLAY_PIECES
	)
	const radius = DEBRIS_DISPLAY_CLUSTER_RADIUS * normalizedRadius
	const angle = index * 137.508 + (index % 4) * 11
	const basePos = center.add(k.Vec2.fromAngle(angle).scale(radius))
	const baseAngle = (index * 83) % 360
	const salvageValue = DEBRIS_DISPLAY_VALUES[
		index % DEBRIS_DISPLAY_VALUES.length
	]
	const visual = SALVAGE_PICKUP_VISUALS[salvageValue]
	const object = k.add([
		k.pos(basePos),
		k.sprite(visual.parts[0].sprite),
		k.anchor("center"),
		k.rotate(baseAngle),
		k.scale(visual.worldScale),
		k.color(visual.color[0], visual.color[1], visual.color[2]),
		k.layer(layers.game2),
		k.z(-2 + normalizedRadius),
		tags.hubRestoration,
		tags.gameLoop,
	])
	return {
		object,
		basePos,
		baseAngle,
		phase: index * 0.91,
		floatSpeed: 0.52 + (index % 5) * 0.07,
	}
}

function spawnRestorationLamps(center: Vec2, initialLevel: number) {
	const lamps: HubRestorationLamp[] = []
	for (let index = 0; index < HUB_RESTORATION_LAMP_COUNT; index++) {
		const lampPos = getHubRestorationLampPosition(center, index + 1)
		let lit = index < initialLevel
		const initialLampColor = lit ? HUB_LAMP_COLOR : HUB_BROKEN_LAMP_COLOR
		const lamp = k.add([
			k.pos(lampPos),
			k.sprite(
				lit ? "hub_progression_lamp" : "hub_progression_lamp_broken"
			),
			k.anchor("center"),
			k.color(
				initialLampColor[0],
				initialLampColor[1],
				initialLampColor[2]
			),
			k.scale(1),
			k.layer(layers.game2),
			k.z(-1),
			tags.hubRestoration,
			tags.gameLoop,
		])
		const light = addLocalLight(lamp, {
			size: 132,
			color: [90, 210, 255],
			opacity: 0,
			pulse: {
				scaleMin: 0.92,
				scaleMax: 1.18,
				scaleSpeed: 3.4,
				opacityMin: 0.72,
				opacityMax: 1,
				opacitySpeed: 2.8,
			},
		})
		const setLit = (nextLit: boolean) => {
			if (lit === nextLit) return
			lit = nextLit
			lamp.use(k.sprite(
				lit ? "hub_progression_lamp" : "hub_progression_lamp_broken"
			))
			const lampColor = lit ? HUB_LAMP_COLOR : HUB_BROKEN_LAMP_COLOR
			lamp.color = k.rgb(lampColor[0], lampColor[1], lampColor[2])
			light.object.opacity = lit ? 0.82 : 0
			light.object.scale = k.vec2(1)
		}
		lamp.onUpdate(() => {
			if (lit) {
				updateLocalLight(light)
			} else {
				light.object.opacity = 0
				light.object.scale = k.vec2(1)
			}
		})
		lamps.push({
			object: lamp,
			isLit: () => lit,
			setLit,
		})
	}
	return lamps
}

function spawnRestorationLampLightning(
	center: Vec2,
	lamps: readonly HubRestorationLamp[]
) {
	k.add([
		k.pos(center),
		k.layer(layers.game2),
		k.z(-2.5),
		{
			draw() {
				for (let index = 0; index < lamps.length; index++) {
					const nextIndex = (index + 1) % lamps.length
					if (nextIndex === 0 && !lamps.every((lamp) => lamp.isLit())) {
						continue
					}
					const startLamp = lamps[index]
					const endLamp = lamps[nextIndex]
					if (!startLamp.isLit() || !endLamp.isLit()) continue
					if (!startLamp.object.exists() || !endLamp.object.exists()) continue

					const start = startLamp.object.pos.sub(center)
					const end = endLamp.object.pos.sub(center)
					const pulse = k.wave(0.76, 1, k.time() * 2.4 + index * 0.47)
					drawLightning({
						start,
						end,
						color: k.rgb(45, 175, 215),
						opacity: 0.16 * pulse,
						width: 3,
						segmentLength: 13,
						amplitude: 7,
						waveCount: 1.7,
						smoothness: 0.74,
						flickerRate: 12,
						seed: 211 + index * 29,
					})
					drawLightning({
						start,
						end,
						color: k.rgb(175, 225, 235),
						opacity: 0.52 * pulse,
						width: 1,
						segmentLength: 13,
						amplitude: 7,
						waveCount: 1.7,
						smoothness: 0.74,
						flickerRate: 12,
						seed: 211 + index * 29,
						branchChance: 0.025,
						branchLength: 7,
					})
				}
			},
		},
		tags.hubRestoration,
		tags.gameLoop,
	])
}

export function getHubRestorationLampPosition(center: Vec2, lampNumber: number) {
	const index = k.clamp(
		Math.round(lampNumber),
		1,
		HUB_RESTORATION_LAMP_COUNT
	) - 1
	return center.add(
		k.Vec2.fromAngle(-90 + index * 45).scale(
			HUB_RESTORATION_FLOOR_STAMP.lampRingRadius
		)
	).add(0, HUB_RESTORATION_FLOOR_STAMP.lampRingOffsetY)
}

function spawnRestorationTier(
	center: Vec2,
	phaseStationPos: Vec2,
	hubHalfBounds: Vec2,
	level: number
) {
	switch (level) {
		case 3:
			spawnSalvageHaulers(center, phaseStationPos, hubHalfBounds)
			break
	}
}

function spawnSalvageHaulers(
	center: Vec2,
	phaseStationPos: Vec2,
	hubHalfBounds: Vec2
) {
	const outsideMargin = 180
	const outsideDestinations = [
		center.add(-hubHalfBounds.x - outsideMargin, -hubHalfBounds.y * 0.72),
		center.add(0, -hubHalfBounds.y - outsideMargin),
		center.add(hubHalfBounds.x + outsideMargin, -hubHalfBounds.y * 0.55),
	]
	const dockingOffsets = [
		k.vec2(-42, 36),
		k.vec2(0, 48),
		k.vec2(42, 36),
	]
	for (let index = 0; index < outsideDestinations.length; index++) {
		const dockPos = phaseStationPos.add(dockingOffsets[index])
		const outsideDestination = outsideDestinations[index]
		const hauler = k.add([
			k.pos(dockPos),
			k.sprite(requirePrimaryVisualSprite(getCompanionVisual("salvager")), { width: 16, height: 16 }),
			k.anchor("center"),
			k.rotate(0),
			k.scale(1),
			k.color(k.WHITE),
			k.opacity(0.92),
			k.layer(layers.game2),
			k.z(-2),
			{
				phase: "waiting" as HaulerPhase,
				phaseTimer: 1.5 + index * 2.3,
				travelStart: dockPos.clone(),
				travelDestination: outsideDestination.clone(),
				travelElapsed: 0,
				travelDuration: 1,
				beginTravel(phase: "outbound" | "returning", destination: Vec2) {
					this.phase = phase
					this.travelStart = this.pos.clone()
					this.travelDestination = destination.clone()
					this.travelElapsed = 0
					this.travelDuration = Math.max(
						0.35,
						this.travelStart.dist(destination) / HAULER_SPEED
					)
				},
				update() {
					if (this.phase === "waiting" || this.phase === "scavenging") {
						this.phaseTimer -= k.dt()
						applySteeringLean(this, this.angle, this.angle)
						if (this.phaseTimer > 0) return
						if (this.phase === "waiting") {
							this.beginTravel("outbound", outsideDestination)
						} else {
							this.beginTravel("returning", dockPos)
						}
						return
					}
					this.travelElapsed += k.dt()
					const progress = k.clamp(
						this.travelElapsed / this.travelDuration,
						0,
						1
					)
					const eased = progress < 0.5
						? 4 * progress * progress * progress
						: 1 - Math.pow(-2 * progress + 2, 3) / 2
					const { lerp, correctedDesiredRot } = lerpAngleBetweenPos(
						this.angle,
						this.pos,
						this.travelDestination,
						1 - Math.exp(-6 * k.dt()),
						-90
					)
					this.angle = lerp
					applySteeringLean(this, lerp, correctedDesiredRot)
					this.pos = this.travelStart.lerp(this.travelDestination, eased)

					if (progress >= 1) {
						this.pos = this.travelDestination
						if (this.phase === "outbound") {
							this.phase = "scavenging"
							this.phaseTimer = k.rand(0.45, 0.85)
						} else {
							this.phase = "waiting"
							this.phaseTimer = 2.5 + index * 0.7
							spawnHaulerDepositPulse(dockPos)
						}
					}
				},
			},
			tags.hubRestoration,
			tags.gameLoop,
		])
		const cargo = HAULER_CARGO_OFFSETS.map(([x, y], cargoIndex) =>
			hauler.add([
				k.sprite("particle2"),
				k.pos(x, y),
				k.scale(0.35),
				k.anchor("center"),
				k.rotate(cargoIndex * 67),
				k.color(150, 170, 176),
				k.opacity(0),
				k.z(-1),
			])
		)
		hauler.onUpdate(() => {
			const carrying = hauler.phase === "returning"
			for (const piece of cargo) {
				piece.opacity = carrying ? 0.88 : 0
				piece.angle += k.dt() * 32
			}
		})
	}
}

function spawnHaulerDepositPulse(pos: Vec2) {
	k.add([
		k.pos(pos),
		k.circle(5, { fill: false }),
		k.anchor("center"),
		k.outline(1, k.rgb(...HUB_GREEN)),
		k.opacity(0.75),
		k.scale(1),
		k.lifespan(0.45, { fade: 0.25 }),
		k.layer(layers.gameEffects),
		k.z(-1),
		tags.hubRestoration,
		tags.gameLoop,
	])
}
